# Maps 2-6 (Fire, Frost, Nature, Arcane, Shadow), designed to match Map 1's structure and tuned numbers:
# 15 regulars (3 tiers of 5), 6 elites, 1 two-phase boss. Enemy card: (name, copies, cost, kind, effect, damage type).
# Tier 1: 31-48 HP, draw 2, 20/20 mana, 10 cards. Tier 2: 53-74 HP, draw 3, 30/30. Tier 3: 84-108 HP, draw 3, 40/30.
# Elites: 125-182 HP, draw 3, 50/30, 15 cards. Boss: ~230 HP, draw 3 (4 in phase 2), 60/40 (50), 20 cards + phase 2 cards.
# About 90% of attacks deal the map element; each map has one visible off-element threat to route around.
# Effects use the enemy card language the engine reads (see parseEnemyCard).
P = 'Physical'

def T1(name, hp, creature, desc, deck, arch='Balanced (5 / 5)', **kw): return dict(name=name, tier=1, rows='1-4', role='Regular', arch=arch, hp=hp, draw=2, mana='20 / 20', creature=creature, desc=desc, deck=deck, **kw)
def T2(name, hp, creature, desc, deck, arch='Balanced (5 / 5)', **kw): return dict(name=name, tier=2, rows='5-9', role='Regular', arch=arch, hp=hp, draw=3, mana='30 / 30', creature=creature, desc=desc, deck=deck, **kw)
def T3(name, hp, creature, desc, deck, arch='Balanced (5 / 5)', **kw): return dict(name=name, tier=3, rows='10-14', role='Regular', arch=arch, hp=hp, draw=3, mana='40 / 30', creature=creature, desc=desc, deck=deck, **kw)
def EL(name, hp, creature, desc, deck, rows, arch, **kw): return dict(name=name, tier='Elite', rows=rows, role='Elite', arch=arch, hp=hp, draw=3, mana='50 / 30', creature=creature, desc=desc, deck=deck, **kw)
def BOSS(name, hp, creature, desc, deck, arch='Two-phase boss', **kw): return dict(name=name, tier='Boss', rows='Boss row', role='Boss', arch=arch, hp=hp, draw='3 (4 in phase 2)', mana='60 / 40 (50 in phase 2)', creature=creature, desc=desc, deck=deck, **kw)

